function corpus(L){const lv=level(),out=[L.keyIdea,...(L.explain[lv]||[]),...(L.explain[lv==='kid'?'adult':'kid']||[])];(L.practice||[]).forEach(p=>p.explain&&!/\{/.test(p.explain)&&out.push(p.explain));return out.flatMap(sentences)}
